parameters.text:
=Analyze this email and return ONLY valid JSON.

From: {{ $json.From }}
Subject: {{ $json.Subject }}
Preview: {{ $json.snippet }}

Return:
{
  "summary": "Factual summary, maximum 25 words",
  "action_required": "Yes or No",
  "action_item": "Specific requested action or None"
}

Rules:
- Return only valid JSON, without markdown.
- Do not invent facts or deadlines.
- Mark action_required Yes only if an action is explicitly requested.

parameters.jsCode:
const summaries = $input.first().json.output;
const emails = $('Gmail').all().map(item => item.json);
const escapeHtml = value => String(value ?? "Not available")
  .replace(/&/g, "&amp;").replace(/</g, "&lt;")
  .replace(/>/g, "&gt;").replace(/"/g, "&quot;")
  .replace(/'/g, "&#39;");

function formatDate(value) {
  if (!value) return "Not available";
  const date = new Date(/^\d+$/.test(String(value)) ? Number(value) : value);
  if (isNaN(date.getTime())) return "Not available";
  return date.toLocaleString("en-IN", {
    timeZone: "Asia/Kolkata", day: "2-digit",
    month: "short", year: "numeric",
    hour: "2-digit", minute: "2-digit"
  });
}

if (!Array.isArray(summaries) || summaries.length !== emails.length) {
  throw new Error("Email and summary counts do not match.");
}

const rows = summaries.map((item, i) => {
  const email = emails[i];
  let ai;
  try {
    ai = JSON.parse(String(item).replace(/^```(?:json)?\s*|\s*```$/g, "").trim());
  } catch {
    throw new Error(`Invalid AI JSON for email ${i + 1}`);
  }
  const action = String(ai.action_required).toLowerCase() === "yes";
  const cells = [
    formatDate(email.internalDate),
    email.From || "Not available",
    email.Subject || "Not available",
    ai.summary || "Not available"
  ].map(value => `<td style="padding:12px;border:1px solid #d1d5db;vertical-align:top">${escapeHtml(value)}</td>`).join("");

  return `<tr style="background:${i % 2 ? "#f1f5f9" : "#ffffff"}">
    ${cells}
    <td style="padding:12px;border:1px solid #d1d5db;vertical-align:top">
      <strong style="color:${action ? "#b45309" : "#15803d"}">${action ? "Yes" : "No"}</strong>
      <div>${escapeHtml(ai.action_item || "None")}</div>
    </td>
  </tr>`;
}).join("");

const html = `
<div style="font-family:Arial,sans-serif;color:#1f2937">
  <h2 style="color:#17365d">Unread Email Summary</h2>
  <p>AI-generated overview of ${summaries.length} unread emails.</p>
  <table style="border-collapse:collapse;width:100%;font-size:13px">
    <thead style="background:#17365d;color:#ffffff">
      <tr>
        ${["Received (IST)", "From", "Subject", "Summary", "Action Required"]
          .map(h => `<th style="padding:12px;border:1px solid #d1d5db;text-align:left">${h}</th>`).join("")}
      </tr>
    </thead>
    <tbody>${rows}</tbody>
  </table>
  <p style="font-size:12px;color:#64748b">
    Generated using n8n and AI. Verify important actions against original emails.
  </p>
</div>`;

return [{ json: { html } }];
